      "description": "Maximize the total profit across all produced products."
    },
    "constraints": [
      {
        "name": "Resource Capacity Constraints",
        "formula": "\\sum_{i \\in P} (Requirement_{ij} \\cdot x_i) \\le Capacity_j \\quad \\forall j \\in R",
